import{z as B,x as r,o as i,c as m,q as l,j as o,D as E,d as e,s as A,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"长序列的内核策略","description":"","frontmatter":{"title":"长序列的内核策略","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ak-longsequence-kernels.md","filePath":"llm/ak-longsequence-kernels.md","lastUpdated":1791063341000}'),d={name:"llm/ak-longsequence-kernels.md"};function h(_,a,p,D,c,f){const n=r("Mermaid");return i(),m("div",null,[a[2]||(a[2]=l('<h1 id="长序列的内核策略" tabindex="-1">长序列的内核策略 <a class="header-anchor" href="#长序列的内核策略" aria-label="Permalink to &quot;长序列的内核策略&quot;">​</a></h1><div class="epigraph"><p>序列变长不改变注意力的公式，改变的是并行度从哪来：KV 轴切开后，softmax 的结合律就是你的归并器。</p><footer>—— 据 Dao et al., 2022；Liu et al., 2023（Ring Attention）整理</footer></div><p><a href="/llm/ak-speculative-interaction">上一课</a>处理了投机带来的形状冲击。本课把 \\(n\\) 推到十万级。<a href="/llm/flashdecoding">FlashDecoding</a> 定过沿 KV 切分与二层 LSE 归并，<a href="/llm/ring-attention">Ring Attention</a> 定过跨设备的序列分片；本课把它们当作同一套内核策略收拢：并行度从哪来、部分结果怎么归并、掩码在长序列下要多管什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三个缺口同一个来源。其一，前填 \\(n=128\\mathrm{k}\\) 时 FlashAttention 的内层循环有上千个 KV 块，但网格并行度仍按 \\(\\mathrm{batch}\\times h_q\\) 展开：单请求、8 个查询头就是只有 8 个线程块，上百个 SM 大半闲置。其二，解码时 KV 读随 \\(n\\) 线性增长，单请求下算术强度贴地，<a href="/llm/arithmetic-intensity-decode">解码的算术强度</a>那本账在长上下文里被放大到难看。其三，显存装不下：\\(128\\mathrm{k}\\) 上下文的整段 KV 本身就超出单卡容量。查询轴没得切（就一行或几行），能切的只剩 KV 轴。</p><p><span class="marginnote">术语翻译：SM 是 GPU 里的计算核心单元，一块卡上有上百个；内核启动时被切成许多线程块去铺满它们。线程块数少于 SM 数时，多出来的 SM 只能空转——好比 8 个工人分到 108 个工位，九成工位闲着。切 KV 段就是临时雇更多工人。</span></p><h3 id="切了-kv-softmax-怎么办" tabindex="-1">切了 KV，softmax 怎么办 <a class="header-anchor" href="#切了-kv-softmax-怎么办" aria-label="Permalink to &quot;切了 KV，softmax 怎么办&quot;">​</a></h3><p>第一课说过每行携带 \\((m,l,O)\\) 三个统计量、且合并满足结合律——沿 KV 切段正是把这条结合律从「块间」用到「段间」：每段独立算出部分结果，再用同一个合并式归并。精确性不丢，因为合并是恒等变换换了个执行顺序。</p><p><span class="marginnote">直觉类比：分段归并像几组评委各读半本书分别打分，最后按各段「见过的最高分」把分数换算到同一尺度再加总。汇总规则只要按结合律写对，结果和一个人从头读到尾完全一致——省的只是让一个人读完全书的时间。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>沿 KV 切分四步。第一，把 KV 均匀切成 \\(S\\) 段，段数按占用算：让 \\(\\mathrm{batch}\\times h_q\\times S\\) 盖过 SM 数。第二，每段独立跑一遍 FA 循环，产出 \\((m_i,l_i,O_i)\\)。第三，归并：\\(m=\\max_i m_i\\)，\\(O=\\sum_i e^{m_i-m}O_i\\)，\\(l=\\sum_i e^{m_i-m}l_i\\)，最后 \\(O/l\\)——数值上与一遍算等价，只是舍入顺序不同。第四，跨设备时段间走点对点环传递 KV 块，通信与段计算重叠，单卡显存不再是上限（Ring Attention 的口径）。服务端还有一路：把 128k 的前填切成若干 4k 段逐段做，与第 5 课的变长接口咬合，首 token 延迟从「全部算完」变成「逐段出活」。</p>',11)),(i(),o(s,null,{default:E(()=>[A(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22KV%20%E5%9D%87%E5%8C%80%E5%88%87%E6%88%90%20S%20%E6%AE%B5%22%5D%20--%3E%20B%5B%22%E6%AF%8F%E6%AE%B5%E7%8B%AC%E7%AB%8B%20FA%EF%BC%9A%E9%83%A8%E5%88%86%E7%BB%93%E6%9E%9C%20m_i%2C%20l_i%2C%20O_i%22%5D%0A%20%20B%20--%3E%20M%5B%22%E5%BD%92%E5%B9%B6%EF%BC%9Am%20%3D%20MAX(m_i)%22%5D%0A%20%20M%20--%3E%20R%5B%22%E6%8C%89%20e%5E%7Bm_i%20%E2%88%92%20m%7D%20%E5%8A%A0%E6%9D%83%E5%B9%B6%20O%20%E4%B8%8E%20l%22%5D%0A%20%20R%20--%3E%20N%5B%22O%20%E2%86%90%20O%20%2F%20l%EF%BC%8C%E5%86%99%E5%9B%9E%22%5D%0A%20%20B%20--%3E%20P%7B%22%E6%AE%B5%E5%9C%A8%E5%88%AB%E7%9A%84%E8%AE%BE%E5%A4%87%3F%22%7D%0A%20%20P%20--%3E%7C%E6%98%AF%7C%20RING%5B%22KV%20%E5%9D%97%E6%B2%BF%E7%8E%AF%E4%BC%A0%E9%80%92%EF%BC%8C%E9%80%9A%E4%BF%A1%E4%B8%8E%E8%AE%A1%E7%AE%97%E9%87%8D%E5%8F%A0%22%5D%0A%20%20RING%20--%3E%20M%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("为什么段数有甜点：切分解决的是并行度，付出的是部分结果的写读与归并——\\(O_i\\) 是 \\(n_q\\times d\\) 的张量，段数翻倍它也翻倍，但相对 KV 流量通常可忽略；段太碎则归并占比上升、每段循环的启动开销显形。所以段数由 SM 数与形状算出，不拍脑袋。错法有三种。把 tile 开小去「多开块」：第一单元的预算表说过这会溢出，方向就错了。用滑窗硬切长序列：那是改语义不是改策略，感受野有损接力是模型课的决定，见 "),t("a",{href:"/llm/sliding-window-attention"},"Sliding Window Attention"),e("。滚动窗口挤掉开头：许多头的权重质量沉在初始 token 上，它们是归一化的锚，切掉锚窗口内权重重新放大、输出崩，见 "),t("a",{href:"/llm/attention-sink"},"Attention Sink"),e("——长序列的掩码策略与数值策略要一起定。")],-1)),(i(),o(s,null,{default:E(()=>[A(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E7%BD%91%E6%A0%BC%E5%B9%B6%E8%A1%8C%E5%BA%A6%20%3D%20batch%20%C3%97%20h_q%20%C3%97%20S%22%5D%20--%3E%20A%5B%22batch%20%E4%B8%8E%20h_q%20%E5%A4%9F%E7%94%A8%E6%97%B6%3A%20S%3D1%20%E5%8D%B3%E5%8F%AF%22%5D%0A%20%20G%20--%3E%20B%5B%22%E5%8D%95%E8%AF%B7%E6%B1%82%E5%8F%AA%E6%9C%89%208%20%E5%9D%97%2C%20%E4%B8%8A%E7%99%BE%20SM%20%E9%97%B2%E7%BD%AE%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%B2%BF%20KV%20%E5%88%87%20S%20%E6%AE%B5%E8%A1%A5%E5%B9%B6%E8%A1%8C%E5%BA%A6%22%5D%0A%20%20C%20--%3E%20D%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E9%83%A8%E5%88%86%E7%BB%93%E6%9E%9C%E5%86%99%E8%AF%BB%E4%B8%8E%E5%BD%92%E5%B9%B6%22%5D%0A%20%20C%20--%3E%20E%5B%22%E6%AE%B5%E5%A4%AA%E7%A2%8E%3A%20%E5%BD%92%E5%B9%B6%E4%B8%8E%E5%90%AF%E5%8A%A8%E5%BC%80%E9%94%80%E5%8D%A0%E6%AF%94%E4%B8%8A%E5%8D%87%22%5D%0A%20%20C%20--%3E%20F%5B%22%E7%94%9C%E7%82%B9%3A%20%E8%AE%A9%E4%B8%89%E6%95%B0%E4%B9%98%E7%A7%AF%E7%9B%96%E8%BF%87%20SM%20%E6%95%B0%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">单请求、\\(h_q=8\\)、A100 有 108 个 SM：不切分时 8 个块占不到一成 SM；沿 KV 切 64 段得 512 块，SM 排满。代价只是多写读一遍 \\(O\\)（\\(n_q\\times d\\)）与统计量——相对 KV 流量不足百分之一。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Ring Attention 的通信量、拓扑与重叠效率属于并行训练课程；本课只认「段间可以走设备」这个接口。位置编码与外推、上下文扩展是模型课题目。KV 装不下时的驱逐与压缩是 KV 管理课程的题目，本课的前提是段都在某个地方存着。策略层面的结论只有一句：长序列的内核手段是同一精确算法换并行度与归并，谁要用近似换速度，先在边界里声明。</p><p><span class="marginnote">为什么重要：很多模型把大量注意力压在最开头几个 token 上，它们像「排水口」一样稳住 softmax 的归一化。滚动窗口一挤掉开头，锚没了，窗口内权重重新放大，输出立刻崩。所以长序列上改掩码、改窗口，永远要先给开头留位置。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长序列的第一缺口是并行度：查询轴切不动，沿 KV 轴切段，段数按 SM 数算。</li><li>段间归并用第一课的结合律：\\(\\max\\) 并 \\(m\\)、指数加权并 \\(l\\) 与 \\(O\\)，精确无近似。</li><li>部分结果的写读是切分的代价，段太碎归并占比上升，甜点由占用算出。</li><li>跨设备切段即 Ring Attention 的接口：KV 块点对点传递，通信与计算重叠。</li><li>掩码与数值要一起定：滑窗是语义决定，attention sink 的锚不能被滚动挤掉。</li><li>出处：Dao et al., 2022；Flash-Decoding, 2023；Liu et al., <em>Ring Attention</em>, 2023。</li></ul>',6))])}const k=B(d,[["render",h]]);export{u as __pageData,k as default};
